//@ expect-stdout: MADAROS_GUM_FO_IMPURE_CTOR_PASS
//@ requires: madaros
// Madaros PASSES this as of the call-result FO work on #1706; lean_single does
// not. The annotation names a real engine boundary rather than hiding a failure:
// the fix lives in self-hosted/ir/lower.sio, and CI's suite compiles with
// souc-stage2, built from self-hosted/compiler/lean_single.sio -- a separate
// compiler that shares none of it.

// Side-effecting pure-field constructors (Mut): FO of field slices is live
// when field inits are pure FO exprs of params. Effects on unrelated state
// (G counter) do not block FO registration of the returned struct's fields.
// No claim that FO tracks the effectful channel — only pure field FO.

struct Pk {
    cl0: f64
    tag: i64
}

var G: i64 = 0

fn make_mut(cl0: f64) -> Pk with Mut {
    G = G + 1
    Pk { cl0: cl0, tag: G }
}

fn make_mut_dbl(x: f64) -> Pk with Mut {
    G = G + 1
    Pk { cl0: x * 2.0, tag: G }
}

fn make_mut_let(x: f64) -> Pk with Mut {
    G = G + 1
    let y = x * 2.0
    Pk { cl0: y, tag: G }
}

fn abs_f(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    return x
}

fn main() with IO, Mut, Div, Epistemic {
    let kx: Knowledge<f64> = measure(5.0, uncertainty: 0.3)
    let x = kx.value

    let v_id = variance_of(make_mut(x).cl0)
    let v_dbl = variance_of(make_mut_dbl(x).cl0)
    let v_let = variance_of(make_mut_let(x).cl0)
    let v_peel = variance_of(x)
    let v_peel2 = variance_of(x * 2.0)

    let pk = make_mut_dbl(x)
    let v_alias = variance_of(pk.cl0)

    print("v_id="); print_f64(v_id); print("\n")
    print("v_dbl="); print_f64(v_dbl); print("\n")
    print("v_let="); print_f64(v_let); print("\n")
    print("v_alias="); print_f64(v_alias); print("\n")

    let ok = abs_f(v_id - v_peel) < 1.0e-9
        && abs_f(v_id - 0.09) < 1.0e-9
        && abs_f(v_dbl - v_peel2) < 1.0e-9
        && abs_f(v_dbl - 0.36) < 1.0e-9
        && abs_f(v_let - v_peel2) < 1.0e-9
        && abs_f(v_alias - v_peel2) < 1.0e-9
    if ok {
        print("MADAROS_GUM_FO_IMPURE_CTOR_PASS\n")
    } else {
        print("MADAROS_GUM_FO_IMPURE_CTOR_FAIL\n")
    }
}

//@ run-pass
//@ requires: madaros
//@ expect-stdout: MADAROS_GUM_FO_SECOND_ORDER_MEAN_PASS

// Second-order mean via diagonal FO Hessian:
//   E₂[f] ≈ f(μ) + ½ Σ_k H_kk σ²_k
// For f(x)=x²: E₂ = μ² + σ²  (exact for Gaussian; Taylor match).
// For f(x)=x³: E₂ = μ³ + 3μ σ².

fn abs_f(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    return x
}

fn main() with IO, Mut, Div, Epistemic {
    // μ=2, σ=0.05 → σ²=0.0025
    let k: Knowledge<f64> = measure(2.0, uncertainty: 0.05)
    let x = k.value

    // First-order mean of x² is just μ²=4.0 (point evaluation)
    let m1 = x * x
    // Second-order: μ² + σ² = 4.0 + 0.0025 = 4.0025
    let m2 = second_order_mean(x * x)
    // Variance still first-order FO: Var(x²) ≈ (2μ)² σ² = 16 * 0.0025 = 0.04
    let v2 = variance_of(x * x)

    // Cube: E₂[x³] = μ³ + 3μ σ² = 8 + 3*2*0.0025 = 8.015
    let m3 = second_order_mean((x * x) * x)

    // Two independent seeds: f=a*b, E₂ = μa·μb (H_aa=H_bb=0 for pure product of
    // independent linears) — bias 0; cross-term not on diagonal.
    let ka: Knowledge<f64> = measure(3.0, uncertainty: 0.1)
    let kb: Knowledge<f64> = measure(4.0, uncertainty: 0.2)
    let a = ka.value
    let b = kb.value
    let mab = second_order_mean(a * b)

    // Sum of squares: f=a²+b² → E₂ = μa²+σa² + μb²+σb²
    // = 9+0.01 + 16+0.04 = 25.05
    let mss = second_order_mean(a * a + b * b)

    print("m1="); print_f64(m1); print("\n")
    print("m2="); print_f64(m2); print("\n")
    print("v2="); print_f64(v2); print("\n")
    print("m3="); print_f64(m3); print("\n")
    print("mab="); print_f64(mab); print("\n")
    print("mss="); print_f64(mss); print("\n")

    let ok = abs_f(m1 - 4.0) < 1.0e-12
        && abs_f(m2 - 4.0025) < 1.0e-9
        && abs_f(v2 - 0.04) < 1.0e-9
        && abs_f(m3 - 8.015) < 1.0e-9
        && abs_f(mab - 12.0) < 1.0e-9
        && abs_f(mss - 25.05) < 1.0e-9
    if ok {
        print("MADAROS_GUM_FO_SECOND_ORDER_MEAN_PASS\n")
    } else {
        print("MADAROS_GUM_FO_SECOND_ORDER_MEAN_FAIL\n")
    }
}

